//! Experimental second stage: test full predicted curves against local spectral background.
//! Windows are generated by trajectories and the shared clock, never hand-selected in audio.
use crate::{
    model::*,
    physics::{distance_m, ecef, enu_vector, Trajectory},
};
fn pixel(s: &Spectrogram, frame: usize, f: f64) -> Option<f64> {
    let x = (f - s.min_hz) / s.bin_hz;
    let background_bins = (10.0f64).max(0.02 * f / s.bin_hz).ceil() as usize;
    if x < background_bins as f64 || x + background_bins as f64 + 2. >= s.bins as f64 {
        return None;
    }
    let j = x.floor() as usize;
    let a = x - j as f64;
    let row = &s.power_db[frame * s.bins..(frame + 1) * s.bins];
    let value = |k: usize| row[k] as f64 * (1. - a) + row[k + 1] as f64 * a;
    let on = 0.25 * value(j - 1) + 0.5 * value(j) + 0.25 * value(j + 1);
    let off = 0.5 * (value(j - background_bins) + value(j + background_bins));
    Some(on - off)
}
fn profile(
    s: &Spectrogram,
    tr: &Trajectory,
    cell: &Candidate,
    c: &Config,
) -> Option<SpectralMatch> {
    let x = ecef(cell.lat, cell.lon, c.observer_height_ellipsoid_m);
    let w = enu_vector(
        cell.lat,
        cell.lon,
        c.wind_east_m_s,
        c.wind_north_m_s,
        c.wind_up_m_s,
    );
    let (emit, r) = tr.cpa(x, c.max_track_gap_s)?;
    if r > c.max_range_m {
        return None;
    }
    let center = emit + r / c.sound_speed_m_s - cell.start_unix_s;
    let speed = tr.state(emit, c.max_track_gap_s)?.1.norm().max(1.);
    let half = (1.5 * r / speed).clamp(10., 45.);
    let lo = (center - half).max(*s.times_s.first()?);
    let hi = (center + half).min(*s.times_s.last()?);
    if hi - lo < 15. || hi - lo < 1.6 * half {
        return None;
    }
    let mut samples = Vec::new();
    for k in 0..96 {
        let at = lo + (hi - lo) * k as f64 / 95.;
        let i = s
            .times_s
            .partition_point(|t| *t < at)
            .min(s.times_s.len() - 1);
        let t = s.times_s[i];
        if samples.last().is_some_and(|p: &(usize, f64, f64)| p.0 == i) {
            continue;
        }
        if let Some((d, r)) = tr.doppler_with_wind(
            x,
            cell.start_unix_s + t,
            c.sound_speed_m_s,
            c.max_track_gap_s,
            w,
        ) {
            if r <= c.max_range_m {
                samples.push((i, t, d));
            }
        }
    }
    if samples.len() < 64 {
        return None;
    }
    let min = samples.iter().map(|p| p.2).fold(f64::INFINITY, f64::min);
    let max = samples
        .iter()
        .map(|p| p.2)
        .fold(f64::NEG_INFINITY, f64::max);
    if max - min < 0.02 {
        return None;
    }
    let score = |tone: f64| {
        let mut sum = 0.;
        let mut n = 0;
        for &(i, _, d) in &samples {
            let mut frame = 0.;
            let mut used = false;
            for h in 1..=3 {
                if let Some(v) = pixel(s, i, tone * h as f64 * d) {
                    frame += v / (h as f64).sqrt();
                    used = true;
                }
            }
            if used {
                sum += frame;
                n += 1;
            }
        }
        if n < 64 {
            f64::NEG_INFINITY
        } else {
            sum / n as f64
        }
    };
    let low = s.min_hz;
    let high = s.min_hz + s.bin_hz * s.bins as f64;
    let step = ((high - low) / 512.).max(s.bin_hz);
    let mut best = (low, f64::NEG_INFINITY);
    let mut tone = low;
    while tone <= high {
        let value = score(tone);
        if value > best.1 {
            best = (tone, value);
        }
        tone += step;
    }
    for k in -10..=10 {
        let t = best.0 + k as f64 * step / 10.;
        let value = score(t);
        if value > best.1 {
            best = (t, value);
        }
    }
    Some(SpectralMatch {
        flight_id: tr.id.clone(),
        tone_hz: best.0,
        contrast_db: best.1,
        window_start_s: lo,
        window_end_s: hi,
        predicted: samples
            .into_iter()
            .map(|(_, t, d)| RidgePoint {
                time_s: t,
                frequency_hz: best.0 * d,
                strength_db: 0.,
            })
            .collect(),
    })
}
pub fn rerank(
    heat: &[Candidate],
    s: &Spectrogram,
    p: &DataPackage,
    c: &Config,
    cancel: &dyn Fn() -> bool,
) -> Result<(Vec<Candidate>, Vec<Candidate>), String> {
    let tracks: Vec<_> = p.flights.iter().map(Trajectory::new).collect();
    let mut cells = Vec::new();
    for seed in heat.iter().take(c.spectral_max_cells) {
        if cancel() {
            return Err("Analysis cancelled".into());
        }
        let mut cell = seed.clone();
        let mut scores: Vec<_> = tracks
            .iter()
            .filter_map(|t| profile(s, t, &cell, c))
            .collect();
        scores.sort_by(|a, b| b.contrast_db.total_cmp(&a.contrast_db));
        let mut independent: Vec<SpectralMatch> = Vec::new();
        for value in scores {
            if independent.iter().all(|s| {
                value.window_end_s <= s.window_start_s || value.window_start_s >= s.window_end_s
            }) {
                independent.push(value);
            }
            if independent.len() == 2 {
                break;
            }
        }
        let scores = independent;
        if scores.is_empty() {
            continue;
        }
        cell.ridge_score = Some(cell.score);
        cell.score = scores.iter().map(|s| s.contrast_db).sum();
        cell.spectral_matches = scores;
        cells.push(cell);
    }
    cells.sort_by(|a, b| b.score.total_cmp(&a.score));
    let mut ranked: Vec<Candidate> = Vec::new();
    for cell in &cells {
        if ranked
            .iter()
            .all(|r| distance_m((r.lat, r.lon), (cell.lat, cell.lon)) > c.mode_separation_m)
        {
            ranked.push(cell.clone());
        }
        if ranked.len() == 10 {
            break;
        }
    }
    for cell in &mut cells {
        cell.spectral_matches.clear();
    }
    Ok((ranked, cells))
}
#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn independent_synthetic_audio_prefers_the_correct_predicted_curves() {
        let c = crate::demo::config();
        let bytes = crate::demo::audio();
        let audio = crate::audio::decode(&bytes, c.max_audio_s).unwrap();
        let (_, spec, _) = crate::audio::spectrogram(&audio, &c).unwrap();
        let seed = |lat, lon, start| Candidate {
            lat,
            lon,
            start_unix_s: start,
            score: 0.,
            matched_events: 0,
            cell_size_m: 100.,
            matches: vec![],
            ridge_score: None,
            spectral_matches: vec![],
        };
        let points = vec![
            seed(crate::demo::LAT, crate::demo::LON, crate::demo::START),
            seed(
                crate::demo::LAT + 0.02,
                crate::demo::LON,
                crate::demo::START,
            ),
            seed(crate::demo::LAT, crate::demo::LON, crate::demo::START + 15.),
        ];
        let (ranked, _) = rerank(&points, &spec, &crate::demo::package(), &c, &|| false).unwrap();
        assert_eq!(ranked[0].start_unix_s, crate::demo::START);
        assert_eq!(ranked[0].lat, crate::demo::LAT);
        assert!(ranked[0].spectral_matches.len() >= 2);
    }
}
